-- Paper & Ink Rice — Neovim Colorscheme (auto-generated by bin/rice-theme)
vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then
  vim.cmd("syntax reset")
end

vim.g.colors_name = "rice"
local raw_mode = "__MODE__"
local mode = (raw_mode == "dark" or raw_mode == "light") and raw_mode or vim.o.background
if vim.o.background ~= mode then
  vim.o.background = mode
end

local p = mode == "dark" and {
  paper  = "#171619",
  block  = "#222023",
  ink    = "#E7E2D5",
  muted  = "#8F8A80",
  rule   = "#3A3636",
  red    = "#DE603B",
  ochre  = "#D7AD59",
  indigo = "#6D84AF",
  pine   = "#7C9987",
} or {
  paper  = "#EEEAE1",
  block  = "#E2DCCF",
  ink    = "#1D1C1A",
  muted  = "#8A8478",
  rule   = "#C8C0B1",
  red    = "#CA4C29",
  ochre  = "#CF9C42",
  indigo = "#2C3E60",
  pine   = "#486455",
}

local cover    = "__COVER__"
local cover_fg = "__COVER_FG__"

local function hi(group, opts)
  vim.api.nvim_set_hl(0, group, opts)
end

-- ── Core UI ───────────────────────────────────────────────
hi("Normal",       { fg = p.ink,   bg = p.paper })
hi("NormalFloat",  { fg = p.ink,   bg = p.block })
hi("FloatBorder",  { fg = p.rule,  bg = p.block })
hi("FloatTitle",   { fg = cover_fg, bg = cover, bold = true })
hi("CursorLine",   { bg = p.block })
hi("CursorColumn", { bg = p.block })
hi("ColorColumn",  { bg = p.block })
hi("Cursor",       { fg = cover_fg, bg = cover })
hi("Visual",       { fg = cover_fg, bg = cover })
hi("Search",       { fg = cover_fg, bg = cover })
hi("IncSearch",    { fg = p.paper, bg = p.ink, bold = true })
hi("CurSearch",    { fg = p.paper, bg = p.ink, bold = true })
hi("MatchParen",   { fg = cover,   bg = p.block, bold = true, underline = true })

-- ── Gutters, Splits & Statusline ──────────────────────────
hi("LineNr",       { fg = p.muted })
hi("CursorLineNr", { fg = cover,   bold = true })
hi("SignColumn",   { fg = p.muted, bg = p.paper })
hi("FoldColumn",   { fg = p.muted, bg = p.paper })
hi("Folded",       { fg = p.muted, bg = p.block, italic = true })
hi("VertSplit",    { fg = p.rule })
hi("WinSeparator", { fg = p.rule })
hi("StatusLine",   { fg = p.ink,   bg = p.block })
hi("StatusLineNC", { fg = p.muted, bg = p.block })
hi("TabLine",      { fg = p.muted, bg = p.block })
hi("TabLineFill",  { bg = p.block })
hi("TabLineSel",   { fg = cover_fg, bg = cover, bold = true })
hi("WinBar",       { fg = p.ink,   bg = p.paper, bold = true })
hi("WinBarNC",     { fg = p.muted, bg = p.paper })

-- ── Popup Menu (Completion) ───────────────────────────────
hi("Pmenu",        { fg = p.ink,   bg = p.block })
hi("PmenuSel",     { fg = cover_fg, bg = cover, bold = true })
hi("PmenuSbar",    { bg = p.block })
hi("PmenuThumb",   { bg = p.rule })

hi("BlinkCmpMenu",          { fg = p.ink,    bg = p.block })
hi("BlinkCmpMenuBorder",    { fg = cover,    bg = p.block })
hi("BlinkCmpMenuSelection", { fg = cover_fg, bg = cover, bold = true })
hi("BlinkCmpGhostText",     { fg = p.muted,  italic = true })


-- ── Messages & Prompts ────────────────────────────────────
hi("ModeMsg",      { fg = cover,   bold = true })
hi("MoreMsg",      { fg = p.pine,  bold = true })
hi("Question",     { fg = p.indigo })
hi("WarningMsg",   { fg = p.ochre, bold = true })
hi("ErrorMsg",     { fg = p.red,   bold = true })
hi("NonText",      { fg = p.rule })
hi("Whitespace",   { fg = p.rule })
hi("SpecialKey",   { fg = p.rule })
hi("Directory",    { fg = p.indigo, bold = true })
hi("Title",        { fg = cover,   bold = true })

-- ── Editorial Syntax Highlighting ─────────────────────────
hi("Comment",      { fg = p.muted, italic = true })
hi("Constant",     { fg = p.ochre })
