hi("Repeat",       { fg = cover,   bold = true })
hi("Label",        { fg = cover })
hi("Operator",     { fg = p.muted })
hi("Keyword",      { fg = cover,   bold = true })
hi("Exception",    { fg = p.red,   bold = true })

hi("PreProc",      { fg = p.indigo })
hi("Include",      { fg = p.indigo })
hi("Define",       { fg = p.indigo })
hi("Macro",        { fg = p.indigo })

hi("Type",         { fg = p.ochre })
hi("StorageClass", { fg = cover })
hi("Structure",    { fg = p.ochre })
hi("Typedef",      { fg = p.ochre })

hi("Special",      { fg = cover })
hi("SpecialChar",  { fg = p.ochre })
hi("Delimiter",    { fg = p.muted })
hi("Underlined",   { underline = true })
hi("Todo",         { fg = cover_fg, bg = cover, bold = true })
hi("Error",        { fg = p.red,   bold = true })

-- ── Treesitter Links ──────────────────────────────────────
hi("@variable",            { fg = p.ink })
hi("@variable.builtin",    { fg = p.indigo, italic = true })
hi("@variable.parameter",  { fg = p.ink, italic = true })
hi("@property",            { fg = p.ink })
hi("@field",               { fg = p.ink })
hi("@function",            { link = "Function" })
hi("@function.builtin",    { fg = p.indigo })
hi("@keyword",             { link = "Keyword" })
hi("@keyword.return",      { fg = cover, bold = true })
hi("@string",              { link = "String" })
hi("@type",                { link = "Type" })
hi("@type.builtin",        { fg = p.ochre, italic = true })
hi("@punctuation.bracket", { fg = p.muted })
hi("@punctuation.delimiter",{ fg = p.muted })
hi("@comment",             { link = "Comment" })
hi("@markup.heading",      { fg = cover, bold = true })
hi("@markup.italic",       { italic = true })
hi("@markup.strong",       { bold = true })
hi("@markup.link",         { fg = p.indigo, underline = true })

-- ── Diagnostics & Git Signs ───────────────────────────────
hi("DiagnosticError", { fg = p.red })
hi("DiagnosticWarn",  { fg = p.ochre })
