hi("DiagnosticUnderlineInfo",  { sp = p.indigo, undercurl = true })
hi("DiagnosticUnderlineHint",  { sp = p.pine,   undercurl = true })

hi("DiffAdd",      { fg = p.pine,   bg = p.block })
hi("DiffChange",   { fg = p.ochre,  bg = p.block })
hi("DiffDelete",   { fg = p.red,    bg = p.block })
hi("DiffText",     { fg = p.indigo, bg = p.block, bold = true })

hi("GitSignsAdd",    { fg = p.pine })
hi("GitSignsChange", { fg = p.ochre })
hi("GitSignsDelete", { fg = p.red })

